    if(url.pathname==='/api/clock'&&request.method==='POST')return clock(request,auth,env,cors);
    if(url.pathname==='/api/employee/time'&&request.method==='GET')return employeeTime(auth,env,cors);
    if(url.pathname==='/api/admin/overview'&&request.method==='GET')return adminOverview(auth,env,cors);
    if(url.pathname==='/api/admin/settings'&&request.method==='GET')return adminSettings(auth,env,cors);
    if(url.pathname==='/api/admin/settings'&&request.method==='PATCH')return updateAdminSettings(request,auth,env,cors);
    if(url.pathname==='/api/admin/employees'&&request.method==='GET')return listEmployees(auth,env,cors);
    if(url.pathname==='/api/admin/employees'&&request.method==='POST')return createEmployee(request,auth,env,cors);
    if(url.pathname==='/api/admin/leads'&&request.method==='GET')return listLeads(url,auth,env,cors);
    if(url.pathname==='/api/admin/leads'&&request.method==='POST')return createLead(request,auth,env,cors);
    if(url.pathname==='/api/admin/time-entries'&&request.method==='GET')return listTimeEntries(url,auth,env,cors);
    if(url.pathname==='/api/admin/payroll'&&request.method==='GET')return payroll(url,auth,env,cors);
    if(url.pathname==='/api/admin/billing'&&request.method==='GET')return adminBilling(auth,env,cors);
    if(url.pathname==='/api/admin/billing/preview'&&request.method==='POST')return billingPreview(request,auth,env,cors);
    if(url.pathname==='/api/admin/billing/accept'&&request.method==='POST')return billingAccept(request,auth,env,cors,url);
    if(url.pathname==='/api/admin/billing/capture'&&request.method==='POST')return billingCapture(request,auth,env,cors);
    if(url.pathname==='/api/admin/billing/cancel'&&request.method==='POST')return billingCancel(request,auth,env,cors);
