async function authenticate(request,env){const h=request.headers.get('Authorization')||'';if(!h.startsWith('Bearer '))return null;const raw=h.slice(7).trim();if(!raw)return null;const tokenHash=await sha256(raw);const row=await env.DB.prepare(`SELECT s.token_hash,s.expires_at,u.*,o.name org_name,o.slug org_slug,o.feature_timekeeping,o.feature_payroll,o.feature_mobile_clocking,o.feature_leads FROM sessions s JOIN users u ON u.id=s.user_id JOIN organizations o ON o.id=u.organization_id WHERE s.token_hash=?`).bind(tokenHash).first();if(!row)return null;if(new Date(row.expires_at)<=new Date()){await env.DB.prepare('DELETE FROM sessions WHERE token_hash=?').bind(tokenHash).run();return null}return{tokenHash,user:row,organization:{id:row.organization_id,name:row.org_name,slug:row.org_slug,feature_timekeeping:row.feature_timekeeping,feature_payroll:row.feature_payroll,feature_mobile_clocking:row.feature_mobile_clocking,feature_leads:row.feature_leads}}}function publicSession(a){return{user:{id:a.user.id,username:a.user.username,displayName:a.user.display_name,jobTitle:a.user.job_title,role:a.user.role,active:!!a.user.active},organization:{id:a.organization.id,name:a.organization.name,slug:a.organization.slug},features:{timekeeping:!!Number(a.organization.feature_timekeeping),payroll:!!Number(a.organization.feature_payroll),mobileClocking:!!Number(a.organization.feature_mobile_clocking),leads:!!Number(a.organization.feature_leads)}}}async function logout(a,env,c){await env.DB.prepare('DELETE FROM sessions WHERE token_hash=?').bind(a.tokenHash).run();return json({ok:true},200,c)}function requireAdmin(a){if(a.user.role!=='admin')throw new HttpError(403,'Administrator access required.')}function requireFeature(a,name){const map={timekeeping:'feature_timekeeping',payroll:'feature_payroll',mobileClocking:'feature_mobile_clocking',leads:'feature_leads'},key=map[name];if(!key||!Number(a.organization[key]))throw new HttpError(403,`Your current Samson's Automation package does not include ${name}.`)}function requireWorkforce(a){if(!Number(a.organization.feature_timekeeping)&&!Number(a.organization.feature_mobile_clocking)&&!Number(a.organization.feature_payroll))throw new HttpError(403,"Your current package does not include workforce tools.")}
async function adminSettings(a,env,c){requireAdmin(a);const o=await env.DB.prepare('SELECT geofence_enabled,geofence_lat,geofence_lng,geofence_radius_m,overtime_threshold,timezone FROM organizations WHERE id=?').bind(a.organization.id).first();return json({geofence:{enabled:!!o.geofence_enabled,latitude:o.geofence_lat,longitude:o.geofence_lng,radiusMeters:o.geofence_radius_m},payroll:{overtimeThreshold:Number(o.overtime_threshold||40)},timezone:o.timezone||'America/New_York'},200,c)}
