async function uniqueUsername(env,orgId,name){const p=String(name).trim().toLowerCase().replace(/[^a-z0-9\s-]/g,'').split(/\s+/).filter(Boolean);let base=p.length>1?`${p[0][0]}${p[p.length-1]}`:p[0]||'employee';base=normalizeUsername(base).slice(0,12)||'employee';let x=base,n=2;while(await env.DB.prepare('SELECT id FROM users WHERE organization_id=? AND username=? COLLATE NOCASE').bind(orgId,x).first()){x=`${base.slice(0,Math.max(1,12-String(n).length))}${n++}`}return x}
