async function updateEmployee(request,a,env,c,id){requireAdmin(a);requireWorkforce(a);const cur=await env.DB.prepare("SELECT * FROM users WHERE id=? AND organization_id=? AND role='employee'").bind(id,a.organization.id).first();if(!cur)throw new HttpError(404,'Employee not found.');const b=await bodyJson(request),display=b.displayName===undefined?cur.display_name:String(b.displayName||'').trim(),job=b.jobTitle===undefined?cur.job_title:String(b.jobTitle||'').trim(),username=b.username===undefined?cur.username:normalizeUsername(b.username),active=b.active===undefined?!!cur.active:!!b.active,rate=b.hourlyRate===undefined?Number(cur.hourly_rate||0):Math.max(0,Number(b.hourlyRate||0));if(!display||username.length<2)throw new HttpError(400,'Employee name and username are required.');if(await env.DB.prepare('SELECT id FROM users WHERE organization_id=? AND username=? COLLATE NOCASE AND id<>?').bind(a.organization.id,username,id).first())throw new HttpError(409,'That username is already in use.');let hash=cur.credential_hash,salt=cur.credential_salt,generatedPin=null;if(b.newPin){validateEmployeePin(b.newPin);const cr=await makeCredential(String(b.newPin),env);hash=cr.hash;salt=cr.salt;generatedPin=String(b.newPin)}await env.DB.prepare('UPDATE users SET username=?,display_name=?,job_title=?,hourly_rate=?,active=?,credential_hash=?,credential_salt=?,failed_attempts=0,locked_until=NULL,updated_at=? WHERE id=? AND organization_id=?').bind(username,display,job,rate,active?1:0,hash,salt,nowIso(),id,a.organization.id).run();if(!active)await env.DB.prepare('UPDATE time_entries SET clock_out_at=? WHERE user_id=? AND organization_id=? AND clock_out_at IS NULL').bind(nowIso(),id,a.organization.id).run();return json({employee:{id,username,displayName:display,jobTitle:job,hourlyRate:rate,active},generatedPin},200,c)}
