async function adminClockEmployee(request,a,env,c,id){requireAdmin(a);requireFeature(a,'timekeeping');const employee=await env.DB.prepare("SELECT id,display_name,active FROM users WHERE id=? AND organization_id=? AND role='employee'").bind(id,a.organization.id).first();if(!employee)throw new HttpError(404,'Employee not found.');if(!employee.active)throw new HttpError(409,'Restore this employee before changing their clock status.');const b=await bodyJson(request),action=String(b.action||'').toLowerCase();if(!['in','out'].includes(action))throw new HttpError(400,'Clock action must be in or out.');const open=await env.DB.prepare('SELECT * FROM time_entries WHERE user_id=? AND organization_id=? AND clock_out_at IS NULL').bind(employee.id,a.organization.id).first(),now=nowIso();const org=await env.DB.prepare('SELECT geofence_lat,geofence_lng FROM organizations WHERE id=?').bind(a.organization.id).first();const fallbackLat=Number.isFinite(Number(org?.geofence_lat))?Number(org.geofence_lat):0,fallbackLng=Number.isFinite(Number(org?.geofence_lng))?Number(org.geofence_lng):0;if(action==='in'){if(open)throw new HttpError(409,`${employee.display_name} is already clocked in.`);const entryId=crypto.randomUUID(),auditId=crypto.randomUUID();await env.DB.batch([env.DB.prepare('INSERT INTO time_entries(id,organization_id,user_id,clock_in_at,clock_in_lat,clock_in_lng,clock_in_accuracy,created_at) VALUES(?,?,?,?,?,?,?,?)').bind(entryId,a.organization.id,employee.id,now,fallbackLat,fallbackLng,null,now),env.DB.prepare('INSERT INTO time_entry_audit(id,organization_id,time_entry_id,changed_by_user_id,old_clock_in_at,old_clock_out_at,new_clock_in_at,new_clock_out_at,reason,created_at) VALUES(?,?,?,?,?,?,?,?,?,?)').bind(auditId,a.organization.id,entryId,a.user.id,null,null,now,null,'Manager clock-in override',now)]);return json({ok:true,action:'in',at:now,employee:{id:employee.id,displayName:employee.display_name},managerOverride:true},200,c)}if(!open)throw new HttpError(409,`${employee.display_name} is not currently clocked in.`);const auditId=crypto.randomUUID();await env.DB.batch([env.DB.prepare('UPDATE time_entries SET clock_out_at=?,clock_out_lat=?,clock_out_lng=?,clock_out_accuracy=? WHERE id=? AND organization_id=?').bind(now,fallbackLat,fallbackLng,null,open.id,a.organization.id),env.DB.prepare('INSERT INTO time_entry_audit(id,organization_id,time_entry_id,changed_by_user_id,old_clock_in_at,old_clock_out_at,new_clock_in_at,new_clock_out_at,reason,created_at) VALUES(?,?,?,?,?,?,?,?,?,?)').bind(auditId,a.organization.id,open.id,a.user.id,open.clock_in_at,open.clock_out_at,open.clock_in_at,now,'Manager clock-out override',now)]);return json({ok:true,action:'out',at:now,employee:{id:employee.id,displayName:employee.display_name},managerOverride:true},200,c)}

async function listLeads(url,a,env,c){requireAdmin(a);requireFeature(a,'leads');const status=url.searchParams.get('status'),limit=Math.max(1,Math.min(100,Number(url.searchParams.get('limit')||50))),before=url.searchParams.get('before');if(status&&status!=='All'&&!LEAD_STATUSES.includes(status))throw new HttpError(400,'Invalid lead status.');let sql='SELECT * FROM leads WHERE organization_id=?',vals=[a.organization.id];if(status&&status!=='All'){sql+=' AND status=?';vals.push(status)}if(before){sql+=' AND created_at<?';vals.push(before)}sql+=' ORDER BY created_at DESC,id DESC LIMIT ?';vals.push(limit+1);const r=await env.DB.prepare(sql).bind(...vals).all(),arr=r.results||[],more=arr.length>limit,rows=arr.slice(0,limit);return json({leads:rows.map(publicLead),nextBefore:more?rows[rows.length-1].created_at:null},200,c)}function publicLead(x){return{id:x.id,name:x.name,phone:x.phone,email:x.email,need:x.need,estimatedValue:Number(x.estimated_value||0),status:x.status,previousStatus:x.previous_status,followupDate:x.followup_date,createdAt:x.created_at,updatedAt:x.updated_at}}
async function createLead(request,a,env,c){requireAdmin(a);requireFeature(a,'leads');const b=await bodyJson(request),name=String(b.name||'').trim(),need=String(b.need||'').trim();if(!name||!need)throw new HttpError(400,'Customer name and need are required.');const id=crypto.randomUUID(),now=nowIso();await env.DB.prepare('INSERT INTO leads(id,organization_id,name,phone,email,need,estimated_value,status,followup_date,created_at,updated_at) VALUES(?,?,?,?,?,?,?,\'New\',?,?,?)').bind(id,a.organization.id,name,String(b.phone||'').trim(),String(b.email||'').trim(),need,Math.max(0,Number(b.estimatedValue||0)),b.followupDate||null,now,now).run();return json({lead:publicLead(await env.DB.prepare('SELECT * FROM leads WHERE id=? AND organization_id=?').bind(id,a.organization.id).first())},201,c)}
async function updateLead(request,a,env,c,id){requireAdmin(a);requireFeature(a,'leads');const cur=await env.DB.prepare('SELECT * FROM leads WHERE id=? AND organization_id=?').bind(id,a.organization.id).first();if(!cur)throw new HttpError(404,'Lead not found.');const b=await bodyJson(request);let status=b.status===undefined?cur.status:String(b.status);if(!LEAD_STATUSES.includes(status))throw new HttpError(400,'Invalid lead status.');let prev=cur.previous_status;if(status==='Suspended'&&cur.status!=='Suspended')prev=cur.status;else if(cur.status==='Suspended'&&status!=='Suspended')prev=null;const name=b.name===undefined?cur.name:String(b.name||'').trim(),need=b.need===undefined?cur.need:String(b.need||'').trim();if(!name||!need)throw new HttpError(400,'Customer name and need are required.');await env.DB.prepare('UPDATE leads SET name=?,phone=?,email=?,need=?,estimated_value=?,status=?,previous_status=?,followup_date=?,updated_at=? WHERE id=? AND organization_id=?').bind(name,b.phone===undefined?cur.phone:String(b.phone||'').trim(),b.email===undefined?cur.email:String(b.email||'').trim(),need,b.estimatedValue===undefined?cur.estimated_value:Math.max(0,Number(b.estimatedValue||0)),status,prev,b.followupDate===undefined?cur.followup_date:(b.followupDate||null),nowIso(),id,a.organization.id).run();return json({lead:publicLead(await env.DB.prepare('SELECT * FROM leads WHERE id=? AND organization_id=?').bind(id,a.organization.id).first())},200,c)}
function rangeParams(url,maxDays=45){const from=url.searchParams.get('from'),to=url.searchParams.get('to');if(!/^\d{4}-\d{2}-\d{2}$/.test(from||'')||!/^\d{4}-\d{2}-\d{2}$/.test(to||''))throw new HttpError(400,'A valid from/to date range is required.');const start=new Date(`${from}T00:00:00.000Z`),end=new Date(`${to}T23:59:59.999Z`);if(end<start)throw new HttpError(400,'End date must not be before start date.');if((end-start)/86400000>maxDays)throw new HttpError(400,`Date range cannot exceed ${maxDays} days.`);return{from,to,start:start.toISOString(),end:end.toISOString()}}
async function listTimeEntries(url,a,env,c){requireAdmin(a);requireFeature(a,'timekeeping');const r=rangeParams(url),limit=Math.max(1,Math.min(500,Number(url.searchParams.get('limit')||250)));const q=await env.DB.prepare(`SELECT t.*,u.display_name,u.job_title,EXISTS(SELECT 1 FROM time_entry_audit ai WHERE ai.organization_id=t.organization_id AND ai.time_entry_id=t.id AND ai.reason='Manager clock-in override') manager_clock_in,EXISTS(SELECT 1 FROM time_entry_audit ao WHERE ao.organization_id=t.organization_id AND ao.time_entry_id=t.id AND ao.reason='Manager clock-out override') manager_clock_out FROM time_entries t JOIN users u ON u.id=t.user_id AND u.organization_id=t.organization_id WHERE t.organization_id=? AND t.clock_in_at BETWEEN ? AND ? ORDER BY t.clock_in_at DESC LIMIT ?`).bind(a.organization.id,r.start,r.end,limit).all();return json({entries:(q.results||[]).map(x=>({id:x.id,userId:x.user_id,displayName:x.display_name,jobTitle:x.job_title,clockInAt:x.clock_in_at,clockOutAt:x.clock_out_at,hours:hoursBetween(x.clock_in_at,x.clock_out_at),editedAt:x.edited_at,editNote:x.edit_note,managerClockIn:!!x.manager_clock_in,managerClockOut:!!x.manager_clock_out}))},200,c)}function hoursBetween(i,o){if(!i)return 0;const e=o?new Date(o):new Date();return Math.max(0,(e-new Date(i))/3600000)}
async function updateTimeEntry(request,a,env,c,id){requireAdmin(a);requireFeature(a,'timekeeping');const cur=await env.DB.prepare('SELECT * FROM time_entries WHERE id=? AND organization_id=?').bind(id,a.organization.id).first();if(!cur)throw new HttpError(404,'Time entry not found.');const b=await bodyJson(request),cin=String(b.clockInAt||''),cout=b.clockOutAt?String(b.clockOutAt):null,reason=String(b.reason||'').trim();if(!cin||Number.isNaN(Date.parse(cin)))throw new HttpError(400,'Valid clock-in time required.');if(cout&&Number.isNaN(Date.parse(cout)))throw new HttpError(400,'Invalid clock-out time.');if(cout&&new Date(cout)<=new Date(cin))throw new HttpError(400,'Clock-out must be after clock-in.');if(reason.length<3)throw new HttpError(400,'Give a short reason for the correction.');const now=nowIso(),auditId=crypto.randomUUID();await env.DB.batch([env.DB.prepare('INSERT INTO time_entry_audit(id,organization_id,time_entry_id,changed_by_user_id,old_clock_in_at,old_clock_out_at,new_clock_in_at,new_clock_out_at,reason,created_at) VALUES(?,?,?,?,?,?,?,?,?,?)').bind(auditId,a.organization.id,id,a.user.id,cur.clock_in_at,cur.clock_out_at,cin,cout,reason,now),env.DB.prepare('UPDATE time_entries SET clock_in_at=?,clock_out_at=?,edited_at=?,edited_by=?,edit_note=? WHERE id=? AND organization_id=?').bind(cin,cout,now,a.user.id,reason,id,a.organization.id)]);return json({ok:true},200,c)}
async function payroll(url,a,env,c){requireAdmin(a);requireFeature(a,'payroll');const r=rangeParams(url,45),org=await env.DB.prepare('SELECT overtime_threshold FROM organizations WHERE id=?').bind(a.organization.id).first(),threshold=Number(org.overtime_threshold||40);const q=await env.DB.prepare(`SELECT u.id,u.display_name,u.hourly_rate,t.clock_in_at,t.clock_out_at FROM users u LEFT JOIN time_entries t ON t.user_id=u.id AND t.organization_id=u.organization_id AND t.clock_in_at BETWEEN ? AND ? AND t.clock_out_at IS NOT NULL WHERE u.organization_id=? AND u.role='employee' AND u.active=1 ORDER BY u.display_name`).bind(r.start,r.end,a.organization.id).all();const map=new Map();for(const x of q.results||[]){if(!map.has(x.id))map.set(x.id,{id:x.id,displayName:x.display_name,hourlyRate:Number(x.hourly_rate||0),hours:0});if(x.clock_in_at&&x.clock_out_at)map.get(x.id).hours+=hoursBetween(x.clock_in_at,x.clock_out_at)}const rows=[...map.values()].map(x=>{const regular=Math.min(threshold,x.hours),ot=Math.max(0,x.hours-threshold),gross=regular*x.hourlyRate+ot*x.hourlyRate*1.5;return{...x,regularHours:regular,overtimeHours:ot,grossEstimate:gross}}).filter(x=>x.hours>0);return json({rows,totals:{regularHours:rows.reduce((s,x)=>s+x.regularHours,0),overtimeHours:rows.reduce((s,x)=>s+x.overtimeHours,0),grossEstimate:rows.reduce((s,x)=>s+x.grossEstimate,0)},overtimeThreshold:threshold},200,c)}
async function adminOverview(a,env,c){requireAdmin(a);const f=featureObjectFromRow(a.organization),week=new Date();week.setUTCHours(0,0,0,0);week.setUTCDate(week.getUTCDate()-week.getUTCDay());const weekIso=week.toISOString(),today=new Date().toISOString().slice(0,10);let active={n:0},due={n:0},follow={results:[]},clock={n:0},hours={h:0},clocked={results:[]},gross=0;if(f.leads){[active,due,follow]=await Promise.all([env.DB.prepare("SELECT COUNT(*) n FROM leads WHERE organization_id=? AND status NOT IN ('Won','Lost','Suspended')").bind(a.organization.id).first(),env.DB.prepare("SELECT COUNT(*) n FROM leads WHERE organization_id=? AND status NOT IN ('Won','Lost','Suspended') AND followup_date IS NOT NULL AND followup_date<=?").bind(a.organization.id,today).first(),env.DB.prepare("SELECT name,need,status FROM leads WHERE organization_id=? AND status NOT IN ('Won','Lost','Suspended') AND followup_date IS NOT NULL AND followup_date<=? ORDER BY followup_date ASC LIMIT 5").bind(a.organization.id,today).all()])}if(f.timekeeping||f.mobileClocking||f.payroll){[clock,hours,clocked]=await Promise.all([env.DB.prepare('SELECT COUNT(*) n FROM time_entries WHERE organization_id=? AND clock_out_at IS NULL').bind(a.organization.id).first(),env.DB.prepare(`SELECT SUM((julianday(COALESCE(clock_out_at,?))-julianday(clock_in_at))*24.0) h FROM time_entries WHERE organization_id=? AND clock_in_at>=?`).bind(nowIso(),a.organization.id,weekIso).first(),env.DB.prepare(`SELECT u.display_name,u.job_title,t.clock_in_at FROM time_entries t JOIN users u ON u.id=t.user_id AND u.organization_id=t.organization_id WHERE t.organization_id=? AND t.clock_out_at IS NULL ORDER BY t.clock_in_at ASC LIMIT 10`).bind(a.organization.id).all()])}if(f.payroll){const rateRows=await env.DB.prepare(`SELECT u.hourly_rate,t.clock_in_at,t.clock_out_at FROM time_entries t JOIN users u ON u.id=t.user_id AND u.organization_id=t.organization_id WHERE t.organization_id=? AND t.clock_in_at>=?`).bind(a.organization.id,weekIso).all();for(const x of rateRows.results||[])gross+=hoursBetween(x.clock_in_at,x.clock_out_at)*Number(x.hourly_rate||0)}return json({features:f,metrics:{activeLeads:Number(active?.n||0),followupsDue:Number(due?.n||0),clockedIn:Number(clock?.n||0),hoursThisWeek:Number(hours?.h||0),grossThisWeek:gross},followups:follow?.results||[],clockedIn:(clocked?.results||[]).map(x=>({displayName:x.display_name,jobTitle:x.job_title,clockInAt:x.clock_in_at}))},200,c)}
async function changePin(request,a,env,c){if(a.user.role!=='employee')throw new HttpError(403,'Employee account required.');const b=await bodyJson(request),cur=String(b.currentPin||''),next=String(b.newPin||'');validateEmployeePin(cur);validateEmployeePin(next);const old=await hashCredential(cur,a.user.credential_salt,env.PIN_PEPPER);if(!safeEqual(old,a.user.credential_hash))throw new HttpError(401,'Current PIN is incorrect.');const cr=await makeCredential(next,env);await env.DB.prepare('UPDATE users SET credential_hash=?,credential_salt=?,failed_attempts=0,locked_until=NULL,updated_at=? WHERE id=? AND organization_id=?').bind(cr.hash,cr.salt,nowIso(),a.user.id,a.organization.id).run();return json({ok:true},200,c)}
function haversineMeters(a,b,c,d){const R=6371000,toRad=x=>x*Math.PI/180,dl=toRad(c-a),dn=toRad(d-b),z=Math.sin(dl/2)**2+Math.cos(toRad(a))*Math.cos(toRad(c))*Math.sin(dn/2)**2;return 2*R*Math.atan2(Math.sqrt(z),Math.sqrt(1-z))}
async function clock(request,a,env,c){requireFeature(a,'mobileClocking');if(a.user.role!=='employee')throw new HttpError(403,'Employee account required.');const b=await bodyJson(request),action=String(b.action||'').toLowerCase(),lat=Number(b.latitude),lng=Number(b.longitude),accuracy=b.accuracy==null?null:Number(b.accuracy);if(!['in','out'].includes(action))throw new HttpError(400,'Clock action must be in or out.');if(!Number.isFinite(lat)||!Number.isFinite(lng))throw new HttpError(400,'A valid GPS location is required to clock in or out.');const org=await env.DB.prepare('SELECT geofence_enabled,geofence_lat,geofence_lng,geofence_radius_m FROM organizations WHERE id=?').bind(a.organization.id).first();let distance=null;if(org.geofence_enabled){if(org.geofence_lat==null||org.geofence_lng==null)throw new HttpError(409,'The employer enabled a GPS boundary but has not configured its location.');distance=haversineMeters(lat,lng,Number(org.geofence_lat),Number(org.geofence_lng));if(distance>Number(org.geofence_radius_m))throw new HttpError(403,'You are outside the approved clock-in/out area.',{distanceMeters:distance,radiusMeters:Number(org.geofence_radius_m)})}const open=await env.DB.prepare('SELECT id FROM time_entries WHERE user_id=? AND organization_id=? AND clock_out_at IS NULL').bind(a.user.id,a.organization.id).first(),now=nowIso();if(action==='in'){if(open)throw new HttpError(409,'You are already clocked in.');await env.DB.prepare('INSERT INTO time_entries(id,organization_id,user_id,clock_in_at,clock_in_lat,clock_in_lng,clock_in_accuracy,created_at) VALUES(?,?,?,?,?,?,?,?)').bind(crypto.randomUUID(),a.organization.id,a.user.id,now,lat,lng,Number.isFinite(accuracy)?accuracy:null,now).run();return json({ok:true,action:'in',at:now,distanceMeters:distance},200,c)}if(!open)throw new HttpError(409,'You are not currently clocked in.');await env.DB.prepare('UPDATE time_entries SET clock_out_at=?,clock_out_lat=?,clock_out_lng=?,clock_out_accuracy=? WHERE id=? AND organization_id=?').bind(now,lat,lng,Number.isFinite(accuracy)?accuracy:null,open.id,a.organization.id).run();return json({ok:true,action:'out',at:now,distanceMeters:distance},200,c)}
async function employeeTime(a,env,c){requireFeature(a,'mobileClocking');if(a.user.role!=='employee')throw new HttpError(403,'Employee account required.');const org=await env.DB.prepare('SELECT geofence_enabled,geofence_radius_m FROM organizations WHERE id=?').bind(a.organization.id).first(),open=await env.DB.prepare('SELECT id,clock_in_at FROM time_entries WHERE user_id=? AND organization_id=? AND clock_out_at IS NULL').bind(a.user.id,a.organization.id).first(),r=await env.DB.prepare('SELECT id,clock_in_at,clock_out_at FROM time_entries WHERE user_id=? AND organization_id=? ORDER BY clock_in_at DESC LIMIT 12').bind(a.user.id,a.organization.id).all();return json({currentEntry:open?{id:open.id,clockInAt:open.clock_in_at}:null,geofence:{enabled:!!org.geofence_enabled,radiusMeters:org.geofence_radius_m},entries:(r.results||[]).map(x=>({id:x.id,clockInAt:x.clock_in_at,clockOutAt:x.clock_out_at}))},200,c)}
// ---------------- v10 platform owner, entitlements, and billing ----------------
function featureObjectFromRow(o){return{timekeeping:!!Number(o.feature_timekeeping),payroll:!!Number(o.feature_payroll),mobileClocking:!!Number(o.feature_mobile_clocking),leads:!!Number(o.feature_leads)}}
function featuresForPackage(p){return{timekeeping:!!Number(p.feature_timekeeping),payroll:!!Number(p.feature_payroll),mobileClocking:!!Number(p.feature_mobile_clocking),leads:!!Number(p.feature_leads)}}
function centsMoney(c){return (Number(c||0)/100).toFixed(2)}
function plusOneMonth(iso=new Date().toISOString()){const d=new Date(iso);const day=d.getUTCDate();d.setUTCDate(1);d.setUTCMonth(d.getUTCMonth()+1);const max=new Date(Date.UTC(d.getUTCFullYear(),d.getUTCMonth()+1,0)).getUTCDate();d.setUTCDate(Math.min(day,max));return d.toISOString()}
async function getSettingsMap(env){const r=await env.DB.prepare('SELECT key,value FROM platform_settings').all();return Object.fromEntries((r.results||[]).map(x=>[x.key,x.value||'']))}
async function sessionResponse(a,env,c){const base=publicSession(a);const sub=await env.DB.prepare(`SELECT s.*,p.name package_name FROM subscriptions s LEFT JOIN packages p ON p.id=s.package_id WHERE s.organization_id=?`).bind(a.organization.id).first();return json({...base,subscription:sub?publicSubscription(sub):null},200,c)}
function publicSubscription(s){return{id:s.id,packageId:s.package_id,packageName:s.package_name||null,pendingPackageId:s.pending_package_id,status:s.status,paymentProvider:s.payment_provider,monthlyCents:Number(s.monthly_cents||0),currentPeriodStart:s.current_period_start,currentPeriodEnd:s.current_period_end,nextChargeAt:s.next_charge_at,autoRenew:!!Number(s.auto_renew),cancelAtPeriodEnd:!!Number(s.cancel_at_period_end),cancellationRequestedAt:s.cancellation_requested_at,lastPaymentAt:s.last_payment_at,lastPaymentCents:Number(s.last_payment_cents||0)}}

async function platformBootstrap(request,env,c){const b=await bodyJson(request);if(!env.PLATFORM_BOOTSTRAP_KEY||!safeEqual(String(b.setupKey||''),String(env.PLATFORM_BOOTSTRAP_KEY)))throw new HttpError(403,'Invalid platform setup key.');const existing=await env.DB.prepare('SELECT COUNT(*) n FROM platform_admins').first();if(Number(existing?.n||0)>0)throw new HttpError(409,'The platform owner account already exists.');const username=normalizeUsername(b.username),display=String(b.displayName||'').trim(),password=String(b.password||'');if(username.length<3||!display)throw new HttpError(400,'Owner name and username are required.');validateAdminPassword(password);const cr=await makeCredential(password,env),id=crypto.randomUUID(),now=nowIso();await env.DB.prepare('INSERT INTO platform_admins(id,username,display_name,credential_hash,credential_salt,active,created_at,updated_at) VALUES(?,?,?,?,?,1,?,?)').bind(id,username,display,cr.hash,cr.salt,now,now).run();return json({ok:true},201,c)}
async function platformLogin(request,env,c){const b=await bodyJson(request),username=normalizeUsername(b.username),password=String(b.password||'');const r=await env.DB.prepare('SELECT * FROM platform_admins WHERE username=? COLLATE NOCASE').bind(username).first();if(!r||!r.active)throw new HttpError(401,'Invalid owner credentials.');if(r.locked_until&&new Date(r.locked_until)>new Date())throw new HttpError(429,'Too many failed attempts. Try again later.');const h=await hashCredential(password,r.credential_salt,env.PIN_PEPPER);if(!safeEqual(h,r.credential_hash)){const n=Number(r.failed_attempts||0)+1,lock=n>=MAX_FAILED_LOGINS?new Date(Date.now()+LOCK_MINUTES*60000).toISOString():null;await env.DB.prepare('UPDATE platform_admins SET failed_attempts=?,locked_until=?,updated_at=? WHERE id=?').bind(lock?0:n,lock,nowIso(),r.id).run();throw new HttpError(401,'Invalid owner credentials.')}await env.DB.prepare('UPDATE platform_admins SET failed_attempts=0,locked_until=NULL,updated_at=? WHERE id=?').bind(nowIso(),r.id).run();const raw=base64Url(randomBytes(32)),hash=await sha256(raw),exp=new Date(Date.now()+12*3600000).toISOString();await env.DB.prepare('INSERT INTO platform_sessions(token_hash,platform_admin_id,expires_at,created_at) VALUES(?,?,?,?)').bind(hash,r.id,exp,nowIso()).run();return json({token:raw,admin:{id:r.id,username:r.username,displayName:r.display_name}},200,c)}
async function authenticatePlatform(request,env){const h=request.headers.get('Authorization')||'';if(!h.startsWith('Bearer '))return null;const th=await sha256(h.slice(7).trim());const r=await env.DB.prepare(`SELECT s.token_hash,s.expires_at,a.* FROM platform_sessions s JOIN platform_admins a ON a.id=s.platform_admin_id WHERE s.token_hash=?`).bind(th).first();if(!r)return null;if(new Date(r.expires_at)<=new Date()){await env.DB.prepare('DELETE FROM platform_sessions WHERE token_hash=?').bind(th).run();return null}return{tokenHash:th,admin:r}}
async function platformMe(pa,env,c){return json({admin:{id:pa.admin.id,username:pa.admin.username,displayName:pa.admin.display_name}},200,c)}
async function platformLogout(pa,env,c){await env.DB.prepare('DELETE FROM platform_sessions WHERE token_hash=?').bind(pa.tokenHash).run();return json({ok:true},200,c)}
async function platformBusinesses(url,pa,env,c){const q=String(url.searchParams.get('q')||'').trim(),like=`%${q}%`;const r=await env.DB.prepare(`SELECT o.id,o.name,o.slug,o.feature_timekeeping,o.feature_payroll,o.feature_mobile_clocking,o.feature_leads,o.created_at,s.status subscription_status,s.monthly_cents,s.package_id,s.next_charge_at,s.auto_renew,p.name package_name,(SELECT COUNT(*) FROM users u WHERE u.organization_id=o.id AND u.role='employee' AND u.active=1) employee_count FROM organizations o LEFT JOIN subscriptions s ON s.organization_id=o.id LEFT JOIN packages p ON p.id=s.package_id WHERE (?='' OR o.name LIKE ? OR o.slug LIKE ?) ORDER BY o.name COLLATE NOCASE LIMIT 250`).bind(q,like,like).all();return json({businesses:(r.results||[]).map(x=>({id:x.id,name:x.name,slug:x.slug,features:featureObjectFromRow(x),subscription:{status:x.subscription_status||'none',monthlyCents:Number(x.monthly_cents||0),packageId:x.package_id,packageName:x.package_name,nextChargeAt:x.next_charge_at,autoRenew:!!Number(x.auto_renew)},employeeCount:Number(x.employee_count||0),createdAt:x.created_at}))},200,c)}
async function platformBusinessDetail(pa,env,c,id){const o=await env.DB.prepare('SELECT * FROM organizations WHERE id=?').bind(id).first();if(!o)throw new HttpError(404,'Business not found.');const sub=await env.DB.prepare(`SELECT s.*,p.name package_name FROM subscriptions s LEFT JOIN packages p ON p.id=s.package_id WHERE s.organization_id=?`).bind(id).first();const intents=await env.DB.prepare(`SELECT bi.*,p.name package_name FROM billing_intents bi JOIN packages p ON p.id=bi.package_id WHERE bi.organization_id=? ORDER BY bi.created_at DESC LIMIT 20`).bind(id).all();const events=await env.DB.prepare('SELECT * FROM billing_events WHERE organization_id=? ORDER BY created_at DESC LIMIT 30').bind(id).all();return json({business:{id:o.id,name:o.name,slug:o.slug,billingEmail:o.billing_email,features:featureObjectFromRow(o),createdAt:o.created_at},subscription:sub?publicSubscription(sub):null,intents:intents.results||[],events:events.results||[]},200,c)}
async function platformUpdateFeatures(request,pa,env,c,id){const b=await bodyJson(request),o=await env.DB.prepare('SELECT id FROM organizations WHERE id=?').bind(id).first();if(!o)throw new HttpError(404,'Business not found.');const f={timekeeping:!!b.timekeeping,payroll:!!b.payroll,mobileClocking:!!b.mobileClocking,leads:!!b.leads};await env.DB.prepare('UPDATE organizations SET feature_timekeeping=?,feature_payroll=?,feature_mobile_clocking=?,feature_leads=? WHERE id=?').bind(f.timekeeping?1:0,f.payroll?1:0,f.mobileClocking?1:0,f.leads?1:0,id).run();await platformAudit(env,pa.admin.id,id,'features.updated',f);return json({ok:true,features:f},200,c)}
async function platformSettings(pa,env,c){const s=await getSettingsMap(env);return json({cashappHandle:s.cashapp_handle||'',venmoHandle:s.venmo_handle||'',paypalMerchantLabel:s.paypal_merchant_label||"Samson's Automation",automaticVenmoConfigured:!!(env.PAYPAL_CLIENT_ID&&env.PAYPAL_CLIENT_SECRET),note:'Cash App and Venmo handles below are for manual payment display. Automatic recurring Venmo billing settles to the PayPal business merchant configured in Worker secrets.'},200,c)}
async function updatePlatformSettings(request,pa,env,c){const b=await bodyJson(request),now=nowIso(),pairs=[['cashapp_handle',String(b.cashappHandle||'').trim()],['venmo_handle',String(b.venmoHandle||'').trim()],['paypal_merchant_label',String(b.paypalMerchantLabel||"Samson's Automation").trim()]];await env.DB.batch(pairs.map(([k,v])=>env.DB.prepare('INSERT INTO platform_settings(key,value,updated_at) VALUES(?,?,?) ON CONFLICT(key) DO UPDATE SET value=excluded.value,updated_at=excluded.updated_at').bind(k,v,now)));await platformAudit(env,pa.admin.id,null,'platform.settings.updated',{cashappHandle:pairs[0][1],venmoHandle:pairs[1][1]});return platformSettings(pa,env,c)}
async function platformAudit(env,adminId,orgId,action,detail){await env.DB.prepare('INSERT INTO platform_audit(id,platform_admin_id,organization_id,action,detail_json,created_at) VALUES(?,?,?,?,?,?)').bind(crypto.randomUUID(),adminId,orgId,action,JSON.stringify(detail||{}),nowIso()).run()}

async function adminBilling(a,env,c){requireAdmin(a);const [pkgs,sub,settings]=await Promise.all([env.DB.prepare('SELECT * FROM packages WHERE active=1 ORDER BY sort_order').all(),env.DB.prepare(`SELECT s.*,p.name package_name FROM subscriptions s LEFT JOIN packages p ON p.id=s.package_id WHERE s.organization_id=?`).bind(a.organization.id).first(),getSettingsMap(env)]);return json({packages:(pkgs.results||[]).map(p=>({id:p.id,name:p.name,monthlyCents:Number(p.monthly_cents),features:featuresForPackage(p),description:p.description})),subscription:sub?publicSubscription(sub):null,currentFeatures:featureObjectFromRow(a.organization),payment:{automaticVenmoConfigured:!!(env.PAYPAL_CLIENT_ID&&env.PAYPAL_CLIENT_SECRET),cashappHandle:settings.cashapp_handle||'',venmoHandle:settings.venmo_handle||'',merchantLabel:settings.paypal_merchant_label||"Samson's Automation"},termsVersion:settings.terms_version||'2026-09-20'},200,c)}
async function packageById(env,id){const p=await env.DB.prepare('SELECT * FROM packages WHERE id=? AND active=1').bind(String(id||'')).first();if(!p)throw new HttpError(404,'Package not found.');return p}
async function previewForPackage(env,orgId,p){const s=await env.DB.prepare('SELECT * FROM subscriptions WHERE organization_id=?').bind(orgId).first();const active=s&&['active','past_due'].includes(s.status)&&s.current_period_end&&new Date(s.current_period_end)>new Date();const old=active?Number(s.monthly_cents||0):0;const next=Number(p.monthly_cents||0);let due=next,effective='immediate';if(active){if(next>old)due=Math.max(0,next-old);else if(next<old){due=0;effective='next_renewal'}else due=0}return{subscription:s||null,amountDueCents:due,effective,newMonthlyCents:next,creditCents:active?Math.min(old,next):0}}
async function billingPreview(request,a,env,c){requireAdmin(a);const b=await bodyJson(request),p=await packageById(env,b.packageId),pr=await previewForPackage(env,a.organization.id,p);return json({package:{id:p.id,name:p.name,monthlyCents:Number(p.monthly_cents),features:featuresForPackage(p),description:p.description},amountDueCents:pr.amountDueCents,effective:pr.effective,creditCents:pr.creditCents},200,c)}
function authorizationText(p){const f=featuresForPackage(p),features=Object.entries(f).filter(([,v])=>v).map(([k])=>({timekeeping:'Timekeeping',payroll:'Payroll Ready',mobileClocking:'Mobile Clocking',leads:'Lead Management'}[k])).join(', ');return `I authorize Samson's Automation to charge $${centsMoney(p.monthly_cents)} per month for ${p.name} (${features}). The subscription renews monthly until canceled. A cancellation received at least 24 hours before the next scheduled charge will not be charged again. Access continues through the paid period unless otherwise stated.`}
async function billingAccept(request,a,env,c,url){requireAdmin(a);const b=await bodyJson(request),p=await packageById(env,b.packageId),mode=String(b.billingMode||'venmo_auto');if(!b.agreed)throw new HttpError(400,'You must agree to the subscription terms and payment authorization.');if(!['venmo_auto','cashapp_manual','venmo_manual'].includes(mode))throw new HttpError(400,'Invalid billing method.');const pr=await previewForPackage(env,a.organization.id,p),settings=await getSettingsMap(env),termsVersion=settings.terms_version||'2026-09-20',acceptId=crypto.randomUUID(),intentId=crypto.randomUUID(),now=nowIso(),authText=authorizationText(p);await env.DB.batch([env.DB.prepare('INSERT INTO terms_acceptances(id,organization_id,accepted_by_user_id,package_id,package_name,monthly_cents,features_json,terms_version,authorization_text,accepted_at) VALUES(?,?,?,?,?,?,?,?,?,?)').bind(acceptId,a.organization.id,a.user.id,p.id,p.name,Number(p.monthly_cents),JSON.stringify(featuresForPackage(p)),termsVersion,authText,now),env.DB.prepare('INSERT INTO billing_intents(id,organization_id,package_id,terms_acceptance_id,amount_cents,billing_mode,status,created_at,updated_at) VALUES(?,?,?,?,?,?,?, ?,?)').bind(intentId,a.organization.id,p.id,acceptId,pr.amountDueCents,mode,'pending',now,now)]);
if(pr.effective==='next_renewal'){await ensureSubscription(env,a.organization.id);await env.DB.prepare('UPDATE subscriptions SET pending_package_id=?,terms_version=?,updated_at=? WHERE organization_id=?').bind(p.id,termsVersion,now,a.organization.id).run();await env.DB.prepare("UPDATE billing_intents SET status='scheduled',updated_at=? WHERE id=?").bind(now,intentId).run();return json({ok:true,scheduled:true,message:'The lower-priced package is scheduled for the next renewal. No immediate charge was made.'},200,c)}
const existing=await env.DB.prepare('SELECT * FROM subscriptions WHERE organization_id=?').bind(a.organization.id).first();if(mode==='venmo_auto'&&existing?.payment_vault_id){if(pr.amountDueCents>0){const charge=await paypalChargeVault(env,existing.payment_vault_id,pr.amountDueCents,intentId);await activatePackage(env,a.organization.id,p,'venmo_auto',existing.payment_vault_id,existing.provider_customer_id,pr.amountDueCents,charge.id,existing);await env.DB.prepare("UPDATE billing_intents SET status='paid',provider_order_id=?,updated_at=? WHERE id=?").bind(charge.id,nowIso(),intentId).run()}else await activatePackage(env,a.organization.id,p,'venmo_auto',existing.payment_vault_id,existing.provider_customer_id,0,null,existing);return json({ok:true,paid:pr.amountDueCents>0},200,c)}
if(mode==='venmo_auto'){if(!env.PAYPAL_CLIENT_ID||!env.PAYPAL_CLIENT_SECRET)throw new HttpError(503,'Automatic Venmo billing is not configured yet.');if(pr.amountDueCents===0&&existing&&!existing.payment_vault_id)throw new HttpError(409,'This account already has paid access but no saved Venmo authorization. To avoid a duplicate charge, switch to automatic Venmo at the next package purchase or contact Samson to arrange the billing-method change.');const returnBase=String(b.returnUrl||'').trim();if(!/^https:\/\//i.test(returnBase)&&!/^http:\/\/localhost/i.test(returnBase)&&!/^http:\/\/127\.0\.0\.1/i.test(returnBase))throw new HttpError(400,'A valid billing return URL is required.');const order=await paypalCreateVenmoVaultOrder(env,pr.amountDueCents||Number(p.monthly_cents),intentId,a,p,returnBase);await env.DB.prepare('UPDATE billing_intents SET provider_order_id=?,updated_at=? WHERE id=?').bind(order.id,nowIso(),intentId).run();return json({approvalUrl:order.approvalUrl,orderId:order.id},200,c)}
await env.DB.prepare("UPDATE billing_intents SET status='manual_pending',updated_at=? WHERE id=?").bind(nowIso(),intentId).run();return json({manual:true,intentId,amountDueCents:pr.amountDueCents,handle:mode==='cashapp_manual'?(settings.cashapp_handle||''):(settings.venmo_handle||''),message:'Manual payments require Samson to confirm receipt before the package activates. Cash App Pay cannot be stored for automatic subscription charges.'},200,c)}
async function billingCapture(request,a,env,c){requireAdmin(a);const b=await bodyJson(request),orderId=String(b.orderId||'');const intent=await env.DB.prepare('SELECT * FROM billing_intents WHERE provider_order_id=? AND organization_id=?').bind(orderId,a.organization.id).first();if(!intent)throw new HttpError(404,'Billing order not found.');if(intent.status==='paid')return json({ok:true,alreadyPaid:true},200,c);const p=await packageById(env,intent.package_id),cap=await paypalCaptureOrder(env,orderId);const v=cap.payment_source?.venmo?.attributes?.vault||cap.payment_source?.venmo?.attribute?.vault||{},vaultId=v.id||null,customerId=v.customer?.id||null;const existing=await env.DB.prepare('SELECT * FROM subscriptions WHERE organization_id=?').bind(a.organization.id).first();await activatePackage(env,a.organization.id,p,'venmo_auto',vaultId||existing?.payment_vault_id||null,customerId||existing?.provider_customer_id||null,Number(intent.amount_cents||0),orderId,existing);await env.DB.prepare("UPDATE billing_intents SET status='paid',updated_at=? WHERE id=? AND organization_id=?").bind(nowIso(),intent.id,a.organization.id).run();return json({ok:true,vaultStatus:v.status||null,automaticRenewalReady:!!(vaultId||existing?.payment_vault_id)},200,c)}
async function billingCancel(request,a,env,c){requireAdmin(a);const s=await env.DB.prepare('SELECT * FROM subscriptions WHERE organization_id=?').bind(a.organization.id).first();if(!s)throw new HttpError(404,'No subscription found.');const now=nowIso();await env.DB.prepare("UPDATE subscriptions SET auto_renew=0,cancel_at_period_end=1,cancellation_requested_at=?,status=CASE WHEN status='inactive' THEN status ELSE 'active' END,updated_at=? WHERE organization_id=?").bind(now,now,a.organization.id).run();await env.DB.prepare('INSERT INTO billing_events(id,organization_id,event_type,provider,status,detail_json,created_at) VALUES(?,?,?,?,?,?,?)').bind(crypto.randomUUID(),a.organization.id,'cancellation_requested',s.payment_provider||'', 'recorded',JSON.stringify({currentPeriodEnd:s.current_period_end,guarantee:'No renewal charge when cancellation is received at least 24 hours before renewal.'}),now).run();return json({ok:true,currentPeriodEnd:s.current_period_end,message:'Automatic renewal is off. Your current paid access remains through the end of the paid period.'},200,c)}
async function ensureSubscription(env,orgId){let s=await env.DB.prepare('SELECT * FROM subscriptions WHERE organization_id=?').bind(orgId).first();if(!s){const now=nowIso();await env.DB.prepare("INSERT INTO subscriptions(id,organization_id,status,monthly_cents,auto_renew,cancel_at_period_end,created_at,updated_at) VALUES(?,?,'inactive',0,0,0,?,?)").bind(crypto.randomUUID(),orgId,now,now).run();s=await env.DB.prepare('SELECT * FROM subscriptions WHERE organization_id=?').bind(orgId).first()}return s}
async function activatePackage(env,orgId,p,provider,vaultId,customerId,paidCents,providerRef,existing=null){existing=existing||await ensureSubscription(env,orgId);const now=nowIso(),isActive=existing.current_period_end&&new Date(existing.current_period_end)>new Date(),start=isActive?existing.current_period_start:now,end=isActive?existing.current_period_end:plusOneMonth(now),f=featuresForPackage(p);await env.DB.batch([env.DB.prepare('UPDATE organizations SET feature_timekeeping=?,feature_payroll=?,feature_mobile_clocking=?,feature_leads=? WHERE id=?').bind(f.timekeeping?1:0,f.payroll?1:0,f.mobileClocking?1:0,f.leads?1:0,orgId),env.DB.prepare(`UPDATE subscriptions SET package_id=?,pending_package_id=NULL,status='active',payment_provider=?,payment_vault_id=COALESCE(?,payment_vault_id),provider_customer_id=COALESCE(?,provider_customer_id),monthly_cents=?,current_period_start=?,current_period_end=?,next_charge_at=?,auto_renew=?,cancel_at_period_end=0,cancellation_requested_at=NULL,canceled_at=NULL,last_payment_at=CASE WHEN ?>0 THEN ? ELSE last_payment_at END,last_payment_cents=CASE WHEN ?>0 THEN ? ELSE last_payment_cents END,updated_at=? WHERE organization_id=?`).bind(p.id,provider,vaultId,customerId,Number(p.monthly_cents),start,end,end,provider==='venmo_auto'?1:0,paidCents,now,paidCents,paidCents,now,orgId),env.DB.prepare('INSERT INTO billing_events(id,organization_id,event_type,amount_cents,provider,provider_reference,status,detail_json,created_at) VALUES(?,?,?,?,?,?,?,?,?)').bind(crypto.randomUUID(),orgId,'package_activated',paidCents,provider,providerRef||null,'success',JSON.stringify({packageId:p.id,monthlyCents:Number(p.monthly_cents)}),now)]);return true}
async function platformMarkPaid(request,pa,env,c,orgId){const b=await bodyJson(request),intent=await env.DB.prepare('SELECT * FROM billing_intents WHERE id=? AND organization_id=?').bind(String(b.intentId||''),orgId).first();if(!intent)throw new HttpError(404,'Manual payment request not found.');if(intent.status==='paid')return json({ok:true},200,c);const p=await packageById(env,intent.package_id),existing=await ensureSubscription(env,orgId);await activatePackage(env,orgId,p,intent.billing_mode,null,null,Number(intent.amount_cents||0),`manual:${intent.id}`,existing);await env.DB.prepare("UPDATE billing_intents SET status='paid',updated_at=? WHERE id=? AND organization_id=?").bind(nowIso(),intent.id,orgId).run();await platformAudit(env,pa.admin.id,orgId,'manual_payment.confirmed',{intentId:intent.id,amountCents:Number(intent.amount_cents||0)});return json({ok:true},200,c)}

function paypalBase(env){return String(env.PAYPAL_ENV||'sandbox').toLowerCase()==='live'?'https://api-m.paypal.com':'https://api-m.sandbox.paypal.com'}
async function paypalAccessToken(env){if(!env.PAYPAL_CLIENT_ID||!env.PAYPAL_CLIENT_SECRET)throw new HttpError(503,'PayPal/Venmo billing credentials are not configured.');const r=await fetch(paypalBase(env)+'/v1/oauth2/token',{method:'POST',headers:{Authorization:'Basic '+btoa(`${env.PAYPAL_CLIENT_ID}:${env.PAYPAL_CLIENT_SECRET}`),'Content-Type':'application/x-www-form-urlencoded'},body:'grant_type=client_credentials'}),j=await r.json();if(!r.ok)throw new HttpError(502,'PayPal authentication failed.');return j.access_token}
async function paypalCreateVenmoVaultOrder(env,amountCents,intentId,a,p,returnUrl){const access=await paypalAccessToken(env),base=paypalBase(env),cancelUrl=returnUrl+(returnUrl.includes('?')?'&':'?')+'billing_cancel=1',successUrl=returnUrl+(returnUrl.includes('?')?'&':'?')+'billing_return=1';const body={intent:'CAPTURE',purchase_units:[{reference_id:intentId,custom_id:intentId,description:`Samson's Automation - ${p.name}`,amount:{currency_code:'USD',value:centsMoney(amountCents)}}],payment_source:{venmo:{experience_context:{brand_name:"Samson's Automation",shipping_preference:'NO_SHIPPING',return_url:successUrl,cancel_url:cancelUrl},attributes:{vault:{store_in_vault:'ON_SUCCESS',usage_type:'MERCHANT',customer_type:'CONSUMER',usage_pattern:'RECURRING_PREPAID'}}}}};const r=await fetch(base+'/v2/checkout/orders',{method:'POST',headers:{Authorization:`Bearer ${access}`,'Content-Type':'application/json','PayPal-Request-Id':intentId},body:JSON.stringify(body)}),j=await r.json();if(!r.ok)throw new HttpError(502,j.message||'Could not start Venmo checkout.');const approval=(j.links||[]).find(x=>['payer-action','approve'].includes(x.rel))?.href;if(!approval)throw new HttpError(502,'Venmo approval link was not returned.');return{id:j.id,approvalUrl:approval}}
async function paypalCaptureOrder(env,orderId){const access=await paypalAccessToken(env),r=await fetch(`${paypalBase(env)}/v2/checkout/orders/${encodeURIComponent(orderId)}/capture`,{method:'POST',headers:{Authorization:`Bearer ${access}`,'Content-Type':'application/json','PayPal-Request-Id':`capture-${orderId}`},body:'{}'}),j=await r.json();if(!r.ok)throw new HttpError(502,j.message||'Venmo payment capture failed.');return j}
async function paypalChargeVault(env,vaultId,amountCents,reference){const access=await paypalAccessToken(env),body={intent:'CAPTURE',purchase_units:[{reference_id:reference,custom_id:reference,amount:{currency_code:'USD',value:centsMoney(amountCents)}}],payment_source:{venmo:{vault_id:vaultId,stored_credential:{payment_initiator:'MERCHANT',usage:'SUBSEQUENT',usage_pattern:'RECURRING_PREPAID'}}}};const r=await fetch(paypalBase(env)+'/v2/checkout/orders',{method:'POST',headers:{Authorization:`Bearer ${access}`,'Content-Type':'application/json','PayPal-Request-Id':reference},body:JSON.stringify(body)}),j=await r.json();if(!r.ok)throw new HttpError(502,j.message||'Recurring Venmo charge could not be created.');const cap=await paypalCaptureOrder(env,j.id);return{id:j.id,capture:cap}}
async function paypalWebhook(request,env,c){/* Webhook verification is intentionally required before trusting token events. */const body=await request.text();if(!env.PAYPAL_WEBHOOK_ID)return json({ok:true,ignored:true,reason:'PAYPAL_WEBHOOK_ID not configured'},200,c);try{const access=await paypalAccessToken(env),event=JSON.parse(body),verifyBody={auth_algo:request.headers.get('paypal-auth-algo'),cert_url:request.headers.get('paypal-cert-url'),transmission_id:request.headers.get('paypal-transmission-id'),transmission_sig:request.headers.get('paypal-transmission-sig'),transmission_time:request.headers.get('paypal-transmission-time'),webhook_id:env.PAYPAL_WEBHOOK_ID,webhook_event:event};const vr=await fetch(paypalBase(env)+'/v1/notifications/verify-webhook-signature',{method:'POST',headers:{Authorization:`Bearer ${access}`,'Content-Type':'application/json'},body:JSON.stringify(verifyBody)}),vj=await vr.json();if(vj.verification_status!=='SUCCESS')throw new HttpError(400,'Invalid PayPal webhook signature.');if(event.event_type==='VAULT.PAYMENT-TOKEN.CREATED'){const tokenId=event.resource?.id,customerId=event.resource?.customer?.id;if(tokenId&&customerId)await env.DB.prepare("UPDATE subscriptions SET payment_vault_id=?,auto_renew=1,updated_at=? WHERE provider_customer_id=? AND payment_provider='venmo_auto'").bind(tokenId,nowIso(),customerId).run()}return json({ok:true},200,c)}catch(e){if(e instanceof HttpError)throw e;throw new HttpError(400,'Invalid PayPal webhook.')}}
async function runBillingCycle(env){const now=nowIso();await env.DB.prepare(`UPDATE organizations SET feature_timekeeping=0,feature_payroll=0,feature_mobile_clocking=0,feature_leads=0 WHERE id IN (SELECT organization_id FROM subscriptions WHERE cancel_at_period_end=1 AND current_period_end<=?)`).bind(now).run();await env.DB.prepare(`UPDATE subscriptions SET status='canceled',canceled_at=COALESCE(canceled_at,?),updated_at=? WHERE cancel_at_period_end=1 AND current_period_end<=?`).bind(now,now,now).run();const due=await env.DB.prepare(`SELECT s.*,COALESCE(s.pending_package_id,s.package_id) charge_package_id FROM subscriptions s WHERE s.status IN ('active','past_due') AND s.auto_renew=1 AND s.cancel_at_period_end=0 AND s.next_charge_at IS NOT NULL AND s.next_charge_at<=? LIMIT 50`).bind(now).all();for(const s of due.results||[]){try{if(s.payment_provider!=='venmo_auto'||!s.payment_vault_id){const retry=new Date(Date.now()+24*3600000).toISOString();await env.DB.prepare("UPDATE subscriptions SET status='past_due',next_charge_at=?,updated_at=? WHERE id=?").bind(retry,nowIso(),s.id).run();continue}const p=await packageById(env,s.charge_package_id),chargeCents=s.pending_package_id?Number(p.monthly_cents):Number(s.monthly_cents||p.monthly_cents),ref=`renew-${s.id}-${Date.now()}`,charge=await paypalChargeVault(env,s.payment_vault_id,chargeCents,ref),newEnd=plusOneMonth(s.current_period_end||now);const f=featuresForPackage(p);await env.DB.batch([env.DB.prepare('UPDATE organizations SET feature_timekeeping=?,feature_payroll=?,feature_mobile_clocking=?,feature_leads=? WHERE id=?').bind(f.timekeeping?1:0,f.payroll?1:0,f.mobileClocking?1:0,f.leads?1:0,s.organization_id),env.DB.prepare("UPDATE subscriptions SET package_id=?,pending_package_id=NULL,status='active',monthly_cents=?,current_period_start=current_period_end,current_period_end=?,next_charge_at=?,last_payment_at=?,last_payment_cents=?,updated_at=? WHERE id=?").bind(p.id,chargeCents,newEnd,newEnd,nowIso(),chargeCents,nowIso(),s.id),env.DB.prepare('INSERT INTO billing_events(id,organization_id,event_type,amount_cents,provider,provider_reference,status,created_at) VALUES(?,?,?,?,?,?,?,?)').bind(crypto.randomUUID(),s.organization_id,'renewal',chargeCents,'venmo_auto',charge.id,'success',nowIso())])}catch(e){console.error('billing cycle error',s.id,e);const retry=new Date(Date.now()+24*3600000).toISOString();await env.DB.prepare("UPDATE subscriptions SET status='past_due',next_charge_at=?,updated_at=? WHERE id=?").bind(retry,nowIso(),s.id).run();await env.DB.prepare('INSERT INTO billing_events(id,organization_id,event_type,amount_cents,provider,status,detail_json,created_at) VALUES(?,?,?,?,?,?,?,?)').bind(crypto.randomUUID(),s.organization_id,'renewal',Number(s.monthly_cents||0),s.payment_provider||'','failed',JSON.stringify({error:String(e.message||e)}),nowIso()).run()}}}
